function actionButton(label,action,primary=false,extra=''){return `<button type="button" class="button ${primary?'primary':''}" data-action="${action}" ${extra}>${esc(label)}</button>`}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3500)}
function resetDemoDialog(){
 dialog(wfText('Reset demo data','รีเซ็ตข้อมูลตัวอย่าง'),`<p>${wfText('Restore the initial sample data for both WEBPARK and Supplier in this browser. Parts due for review will be available to send again.','คืนข้อมูลตัวอย่างเริ่มต้นของทั้ง WEBPARK และ Supplier ในเบราว์เซอร์นี้ รายการที่ถึงรอบทบทวนจะกลับมาให้ทดลองส่งอีกครั้ง')}</p><p class="demo-reset-warning">${wfText('All trial changes, including sent requests, cost entries, approvals, added parts and edited formulas, will be removed. Your selected account and language will be kept.','ข้อมูลที่ทดลองเปลี่ยนทั้งหมด เช่น คำขอที่ส่ง ต้นทุนที่กรอก การอนุมัติ ชิ้นส่วนที่เพิ่ม และสูตรที่แก้ไข จะถูกล้าง โดยคงบัญชีและภาษาที่ใช้งานไว้')}</p><label class="check"><input type="checkbox" id="confirm-reset-demo">${wfText('I confirm resetting all demo changes.','ยืนยันล้างข้อมูลที่ทดลองทำและคืนข้อมูลตัวอย่างเริ่มต้น')}</label>`,actionButton(wfText('Reset to initial data','รีเซ็ตเป็นข้อมูลเริ่มต้น'),'confirm-reset-demo',true));
}
function confirmResetDemo(){
 if(!document.getElementById('confirm-reset-demo')?.checked)return toast(wfText('Confirm before resetting.','กรุณาติ๊กยืนยันก่อนรีเซ็ตข้อมูล'));
 try{localStorage.removeItem(STORE)}catch{return toast(wfText('Could not reset data. Please try again.','รีเซ็ตข้อมูลไม่ได้ กรุณาลองอีกครั้ง'))}
 location.hash=portal==='roki'?'schedule':'requests';location.reload();
}
