function audit(action,reason=''){db.audit.unshift({action,user:user.name,at:timestamp(),reason});persist()}
function login(){const available=users.filter(u=>u.portal===portal);document.getElementById('app').innerHTML=`<div class="login-layout"><section class="login-story">${logo()}<div><p style="text-transform:uppercase;letter-spacing:2px;font-size:10px">${portal==='roki'?'Purchasing workspace':'Supplier workspace'}</p><h1>${portal==='roki'?'Clear prices. Confident decisions.':'Your quotations, connected to ROKI.'}</h1><p>${portal==='roki'?'Compare cost revisions, manage price review requests, and move quotations through a traceable approval workflow.':'Prepare detailed quotations, approve them within your company, and respond to price update requests in one place.'}</p></div><small>ROKI (THAILAND) CO., LTD. · Supplier Price</small></section><section class="login-main"><div class="login-lang">${I18N.switcher()}</div><div class="login-form"><p class="eyebrow">${portal==='roki'?'ROKI':'Supplier'} portal</p><h2>Welcome to your workspace</h2><p>Select an individual demo account to explore its role and permissions.</p><label for="demo-account">Demo user account</label><select id="demo-account">${available.map(u=>`<option value="${u.id}">${esc(u.name)} · ${u.role}${u.supplier?' · '+esc(supplierName(u.supplier)):''}</option>`).join('')}</select><div id="account-info" class="account-info"></div>${actionButton('Enter '+(portal==='roki'?'ROKI':'supplier')+' workspace','login',true)}<a class="portal-switch" href="${portal==='roki'?'supplier':'roki'}.html">Open ${portal==='roki'?'Supplier':'ROKI'} portal →</a><div class="login-note">Local interactive demo · No password authentication or server access control. Changes are saved in this browser. Supplier notifications are simulated; no emails are sent.</div></div></section></div>`;accountInfo();document.getElementById('demo-account').onchange=accountInfo;}
function accountInfo(){const u=users.find(u=>u.id===document.getElementById('demo-account').value);document.getElementById('account-info').innerHTML=`<strong>${esc(u.email)}</strong><br>${u.supplier?esc(supplierName(u.supplier)):'ROKI Thailand'} · ${u.role} role<br>${rfqAccountDescription(u)}`;}
function shell(content,page){const nav=navs();const parent=workflowCanOpen(page)?recordParentPage(page,route().split('/')[1]):'';const activePage=nav.some(([,id])=>id===parent)?parent:'';return `<div class="layout"><aside class="sidebar"><a href="#overview" class="brand">${logo()}</a><div class="portal-tag">${portal==='roki'?'ROKI PURCHASING':'SUPPLIER WORKSPACE'}</div><nav class="side-nav">${nav.map(([n,id,t,g],idx)=>`${g&&g!==nav[idx-1]?.[3]?`<div class="nav-group">${workflowGroup(g)}</div>`:''}<a class="${activePage===id?'active':''}" href="#${id}">${icon(n)}<span>${t}</span>${deskNavBadge(id)}</a>`).join('')}</nav><div class="sidebar-bottom">${portal==='roki'?`<div class="support-card"><strong>${portal==='roki'?'Automatic requests':'Your company’s quotations'}</strong>${portal==='roki'?'The system sends review requests to Suppliers when they are due.':'Issue → Supplier Approve<br>Then ROKI Issue → Check → Approve'}</div>`:''}<div class="user"><div class="avatar">${esc(user.name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</div><div><strong>${esc(user.name)}</strong><small>${esc(user.role)} · ${portal==='roki'?'ROKI':esc(suppliers.find(s=>s.id===user.supplier).code)}</small></div></div></div></aside><main class="main"><div class="demo-banner"><span>Interactive local demo · Browser data only · Notifications & e-signatures are simulated</span><a href="${portal==='roki'?'supplier':'roki'}.html" target="_blank" rel="noopener">Open ${portal==='roki'?'Supplier':'ROKI'} portal ↗</a></div><header class="topline"><div class="breadcrumb">${portal==='roki'?'ROKI workspace':esc(supplierName(user.supplier))}<span>›</span><strong>${esc(detailBreadcrumb(page,nav))}</strong></div><div class="top-actions"><button type="button" class="button demo-reset-button" data-action="reset-demo">${wfText('Reset demo data','รีเซ็ตข้อมูลตัวอย่าง')}</button>${I18N.switcher()}<span>${esc(user.name)} · ${esc(user.role)}</span><button data-action="logout" class="link-button">Switch account</button></div></header><nav class="mobile-nav">${nav.map(([,id,t])=>`<a href="#${id}" class="${activePage===id?'active':''}"${activePage===id?' aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="content">${content}</div></main></div>`}
function heading(eyebrow,title,sub,actions=''){return `<div class="heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p class="subtitle">${esc(sub)}</p></div><div class="actions">${actions}</div></div>`}
function activityEntries(entries){return entries.length?entries.map(t=>`<div class="audit-entry" ${t.quote?detailRowAttrs('quote/'+t.quote):''}><strong>${esc(t.action)}</strong>${t.quote?` · <a href="#quote/${esc(t.quote)}" class="link-button">${esc(t.quote)}</a>`:''}<small>${esc(t.user)} · ${esc(t.at)}</small>${t.reason?`<p>${esc(t.reason)}</p>`:''}</div>`).join(''):'<div class="empty">No activity yet.</div>'}
function accounts(){return heading('Supplier directory','Supplier accounts','Individual Issue and Approve accounts grouped by supplier company.')+suppliers.map(s=>`<section class="panel" style="margin-bottom:20px"><div class="panel-title"><div><h2>${detailRecordLink('supplier/'+s.id,s.name)}</h2><small>${esc(s.code)} · ${db.items.filter(i=>i.supplier===s.id).length} item–supplier pairs</small></div>${statusPill('Active','green')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Permissions</th></tr></thead><tbody>${users.filter(u=>u.supplier===s.id).map(u=>`<tr ${detailRowAttrs('account/'+u.id)}><td><strong>${esc(u.name)}</strong></td><td>${esc(u.email)}</td><td>${statusPill(u.role,u.role==='Issue'?'blue':'green')}</td><td>${u.role==='Issue'?'Prepare, revise & issue quotations':'Approve and submit quotations to ROKI'}</td></tr>`).join('')}</tbody></table></div></section>`).join('')+'<p class="footer-note">Demo accounts are predefined. Production user provisioning and authentication require a server.</p>'}
function historyView(){const entries=visibleQuotes().flatMap(q=>q.trail.map(t=>({...t,quote:q.id}))).reverse();return heading('Traceability','Revision history','Quotation revisions, approval actions, and reasons are retained together.')+`<section class="panel"><div class="panel-title"><h2>Quotation audit trail</h2></div>${activityEntries(entries)}</section>`}
function exportsView(){const approved=visibleQuotes().filter(q=>priceValidity(q)==='active');return heading(wfText('Active approved quotations','ใบเสนอราคาที่ใช้ปัจจุบัน'),wfText('Active price export','ส่งออกราคาปัจจุบัน'),'Export final approved prices for review before preparing your SAP upload.',actionButton(wfText('Download active prices CSV','ดาวน์โหลดราคาปัจจุบัน CSV'),'export',true))+`<div class="highlight-note blue">${wfText("Export includes only prices effective today; future and historical approvals remain in Price history. This CSV is for review; the SAP import template is still required.","ส่งออกเฉพาะราคาที่มีผลปัจจุบัน ราคาอนุมัติล่วงหน้าและราคาเก่าดูได้ในประวัติราคา CSV นี้ใช้ตรวจสอบ ยังต้องมี Template SAP จริง")}</div><section class="panel"><div class="panel-title"><h2>${wfText('One active quotation per part / supplier','ใบราคาปัจจุบันหนึ่งใบต่อชิ้นส่วน / Supplier')}</h2>${statusPill(approved.length+' approved','green')}</div>${quoteTable(approved)}</section>`}
let compareWith='baseline',detailTab=null,reportCode='';
const pctOf=(a,b)=>b?(a-b)/b*100:0;
const signedPct=(a,b)=>b?`${pctOf(a,b)>0?'+':''}${pctOf(a,b).toFixed(2)}%`:'—';
function deltaCell(now,was){if(was==null)return '<td class="num">—</td>';const d=r2(now-was);return `<td class="num delta ${d<0?'down':d>0?'up':'same'}">${d>0?'+':''}${cash(d)}</td>`}
function latestApproved(itemId,exclude){return db.quotes.filter(q=>q.item===itemId&&q.status==='Approved'&&q.id!==exclude&&q.effective<=TODAY).sort(approvedOrder).at(-1)}
function startingCosts(itemId){const it=db.items.find(i=>i.id===itemId),q=latestApproved(itemId);return q?adaptCosts(q.costs,it.format):blankCosts(it.format)}
function costsForEdit(q){return structuredClone(q.costs)}
function partLink(code){const target=db.items.find(i=>i.code===code&&(portal==='roki'||i.supplier===user.supplier));const q=target&&latestApproved(target.id);return q?`<a class="link-button" href="#quote/${q.id}" title="Open the approved quotation for this part">${esc(code)}</a>`:esc(code)}
function quoteBaselines(q){const list=[];if(q.baseline)list.push({id:'baseline',label:`approved Rev. ${q.baseline.revision} · ${date(q.baseline.date||q.baseline.effective)}`,snap:q.baseline});(q.versions||[]).forEach((v,i)=>list.push({id:'v'+i,label:`returned Rev. ${v.revision} · ${v.at}`,snap:{...v,date:null}}));return list}
function comparisonPanel(q){
const bases=quoteBaselines(q),base=bases.find(b=>b.id===compareWith)||bases[0],secs=sectionsOf(q.costs),now=totals(q.costs),was=base?totals(base.snap.costs):null;const compareSecs=[...secs,...(base?sectionsOf(base.snap.costs).filter(s=>!secs.some(n=>n.key===s.key)):[])];
const row=(letter,label,a,b,cls='')=>`<tr class="${cls}"><td>${letter?`<span class="letter">${letter}</span>`:''}${label}</td><td class="num">${b==null?'—':cash(b)}</td><td class="num price">${cash(a)}</td>${deltaCell(a,b)}<td class="num">${b==null?'—':signedPct(a,b)}</td></tr>`;
const tab=detailTab&&secs.some(s=>s.key===detailTab)?detailTab:secs[0].key;
const showSpare=q.costs.spare||base?.snap.costs.spare;
return `<section class="panel"><div class="panel-title"><div><h2>Cost comparison</h2><small>${base?'Original and revised costs side by side, as on the paper quotation':'First quotation for this item–supplier pair · nothing to compare yet'}</small></div>${bases.length?`<select id="compare-with" aria-label="Compare with">${bases.map(b=>`<option value="${b.id}" ${b===base?'selected':''}>Compare with ${esc(b.label)}</option>`).join('')}</select>`:''}</div><div class="table-wrap"><table class="data-table compare-table"><thead><tr><th>Cost category</th><th class="num">Original${base?' · Rev. '+base.snap.revision:''}</th><th class="num">Revised · Rev. ${q.revision}</th><th class="num">Change · THB</th><th class="num">Change · %</th></tr></thead><tbody>${compareSecs.map(s=>row(s.letter,s.label,now.sections[s.key]?.value||0,was?.sections[s.key]?.value)).join('')}${row('','Subtotal',now.subtotal,was?.subtotal,'subtotal')}${row('',`Profit & admin <small>${q.costs.profit}% × ${profitBase(q.costs).label}</small>`,now.profit,was?.profit)}${showSpare?row('',`Spare part cost <small>${q.costs.spare}% × ${spareBase(q.costs).label}</small>`,now.spare,was?.spare):''}${row('','Total quoted unit price',now.total,was?.total,'total-row')}</tbody></table></div><div class="cost-tabs">${secs.map(s=>{const changed=was&&now[s.letter]!==was[s.letter];return `<button type="button" class="${s.key===tab?'active':''}" data-cmp-tab="${s.key}">${s.letter} · ${s.label}${changed?' <b class="changed-dot" aria-label="changed"></b>':''}</button>`}).join('')}</div>${lineCompare(q.costs,base?.snap.costs,secs.find(s=>s.key===tab))}</section>`}
function lineCompare(c,old,s){
const rows=c[s.key]||[],prev=old?.[s.key]||[],oldSection=old?sectionsOf(old).find(x=>x.key===s.key):null,n=Math.max(rows.length,prev.length);
if(!n)return '<div class="empty">No lines in this cost category.</div>';
const fmt=(f,v)=>v==null?'—':f[2]==='number'?Number(v).toLocaleString('en-US',{maximumFractionDigits:6}):esc(v||'—');
const body=[...Array(n)].map((_,i)=>{const r=rows[i],p=prev[i];return `<tr class="${old&&!p?'added':!r?'removed':''}">${s.fields.map(f=>{const ch=old&&r&&p&&String(r[f[0]])!==String(p[f[0]]);const now=!r?'—':f[0]==='partNo'?partLink(r.partNo):fmt(f,r[f[0]]);return `<td class="${f[2]==='number'?'num ':''}${ch?'changed':''}">${ch?`<s>${fmt(f,p[f[0]])}</s> `:''}${now}</td>`}).join('')}<td class="num">${p&&oldSection?cash(amountOf(old,oldSection,p)):'—'}</td><td class="num price">${r?cash(amountOf(c,s,r)):'—'}</td>${deltaCell(r?amountOf(c,s,r):0,p&&oldSection?amountOf(old,oldSection,p):null)}</tr>`}).join('');
const adj=(s.adj||[]).map(a=>`<span>${a.label}: ${old&&old[a.key]!==c[a.key]?`<s>${old[a.key]}%</s> `:''}<strong>${c[a.key]}%</strong>${a.choices?` of ${lcFirst(adjChoice(c,a).label)}`:''}</span>`).join('');
return `<div class="table-wrap"><table class="data-table line-compare"><thead><tr>${s.fields.map(f=>`<th class="${f[2]==='number'?'num':''}">${f[1]}</th>`).join('')}<th class="num">Original</th><th class="num">Revised</th><th class="num">Change</th></tr></thead><tbody>${body}</tbody></table></div><div class="compare-foot">${adj}<span>${esc(s.formula)}</span>${old?'<span><i class="changed-swatch"></i>Changed value · the struck-through figure is the original</span>':''}</div>`}
function quoteDetail(id){const q=visibleQuotes().find(q=>q.id===id);if(!q)return '<div class="empty">Quotation unavailable for this account. <a href="#quotes" class="link-button">Return to quotations</a></div>';const item=itemOf(q),diff=q.total-(q.previous??q.total);const steps=['Supplier Issue','Supplier Approve','ROKI Issue','ROKI Check','ROKI Approve'];const current={Draft:0,Reverted:0,'Supplier approval':1,'ROKI Issue':2,'ROKI Check':3,'ROKI Approve':4,Approved:5,Rejected:-1}[q.status];
return heading(q.format+' · '+q.id,item.name,item.code+' / '+supplierName(q.supplier)+' / Revision '+q.revision,`<a href="#quotes" class="button">Back to quotations</a><a href="#print/${q.id}" class="button primary">${icon('file')}Quotation form</a>${canEdit(q)?`<button class="button primary" data-edit="${q.id}">Edit quotation</button>`:''}`)+`<div class="page-grid"><div class="stack"><section class="panel"><div class="status-strip">${statusBadge(q.status)}<strong class="next-owner">${workflowNext(q)}</strong><p>${flowSteps().map(s=>s[0]).join(' → ')}</p></div><div class="body-pad detail-meta"><div><label>RTP code</label><p>${esc(item.rtp||'—')}</p></div><div><label>Rev. no. / drawing</label><p>${esc(q.drawing)}</p></div><div><label>${cfgOf(q.costs).qtyLabel}</label><p>${Number(q.quantity).toLocaleString()} pcs</p></div><div><label>Quotation date</label><p>${date(q.quoteDate)}</p></div><div><label>Beginning / effective</label><p>${date(q.effective)}</p></div><div><label>Supplier code</label><p>${esc(suppliers.find(s=>s.id===q.supplier).code)}</p></div></div><div class="detail-prices"><div><label>Previous approved price</label><strong>${q.previous==null?'—':'฿'+cash(q.previous)}</strong></div>${icon('arrow')}<div><label>Proposed unit price</label><strong>฿${cash(q.total)}</strong></div></div><div class="q-change ${diff<0?'down':diff>0?'up':'same'}">${q.previous==null?'First quotation for this part · no previous approved price':`${diff<0?'↘':diff>0?'↗':'→'} ${diff>0?'+':''}${cash(diff)} THB / pc · ${signedPct(q.total,q.previous)} from previous approved price`}</div></section>${sourceLinks(q)}${quotationHistoryPanel(q.item,{current:q.id})}${detailPanel(wfText('Calculation model','สูตรคำนวณราคาซื้อ'),'<strong>'+esc(formulaLabel(q.costs.fv))+'</strong><p>'+wfText('Supplier costs are calculated using the version selected on the request.','ใช้ต้นทุนที่ Supplier กรอกคำนวณตามเวอร์ชันสูตรที่เลือกไว้ในคำขอ')+'</p>')}${comparisonPanel(q)}<section class="panel"><div class="panel-title"><h2>Revision reason & supporting files</h2></div><div class="body-pad"><p>${esc(q.remark)}</p>${q.attachments.length?`<div class="attachment-list">${q.attachments.map((f,i)=>`<button class="attachment-pill" data-file="${i}" data-quote="${q.id}">${f.kind==='drawing'?'PDF drawing':'Part image'} · ${esc(f.name)} ↓</button>`).join('')}</div>`:'<p class="muted-note">No attachments for this demo quotation.</p>'}</div></section><section class="panel"><div class="panel-title"><h2>${wfText("Activity log","ประวัติการดำเนินการ")}</h2><span class="muted-note">${q.versions.length} saved previous revisions</span></div>${activityEntries(q.trail)}</section></div><aside class="stack">${quotationBeforeTimeline(q)?`<div data-timeline-phase="before">${quotationBeforeTimeline(q)}</div>`:''}<div data-timeline-phase="after">${quotationAfterTimeline(q)}</div><section class="panel"><div class="panel-title"><h2>Your next action</h2><span class="badge gray">${esc(user.role)}</span></div><div class="body-pad">${quoteActions(q)}</div></section><section class="panel"><div class="panel-title"><h2>Price history</h2></div><div class="body-pad">${miniHistory(q.item)}<a class="text-link" href="#reports/${encodeURIComponent(item.code)}">Full price history ${icon('arrow')}</a></div></section><div class="highlight-note blue" style="margin-bottom:0">Supplier approval uses account confirmation. ROKI review actions include a simulated e-sign confirmation in this demo.</div></aside></div>`}
function miniHistory(itemId){const h=db.history.filter(x=>x.item===itemId).sort((a,b)=>b.effective.localeCompare(a.effective)).slice(0,4);return h.length?`<div class="mini-history">${h.map(x=>`<div><span>${date(x.effective)}</span><strong>฿${cash(x.price)}</strong></div>`).join('')}</div>`:'<p>No approved prices yet.</p>'}
function quoteActions(q){if(canEdit(q))return `<p>Prepare the revised costs and add a reason before issuing for supplier approval.</p><button class="button primary" style="width:100%;margin-top:15px" data-edit="${q.id}">Edit & issue quotation</button>`;if(pendingForRole(q))return `<p>${portal==='supplier'?'Review the costs and remarks, then approve to submit this quotation to ROKI.':'Review the quotation before completing your assigned '+user.role.toLowerCase()+' step.'}</p><button class="button primary" style="width:100%;margin-top:15px" data-transition="advance" data-id="${q.id}">${portal==='supplier'?'Approve & submit to ROKI':'Sign & complete '+user.role.toLowerCase()}</button><button class="button" style="width:100%;margin-top:10px;color:#7650a4;border-color:#d7bff1" data-transition="revert" data-id="${q.id}">Return for correction</button>${portal==='roki'?`<button class="button danger" style="width:100%;margin-top:10px" data-transition="reject" data-id="${q.id}">Reject quotation</button>`:''}`;return `<p>${q.status==='Approved'?'This quotation has completed final ROKI approval.':q.status==='Rejected'?'This quotation was rejected. A supplier issuer can prepare a new quotation.':'No action is assigned to your current role at this step. Switch to the appropriate account to continue the demo.'}</p>`}
let editorItem=null,editorRequest=null;
function newQuote(itemId,request){if(portal!=='supplier'||user.role!=='Issue')return toast('Only supplier issuers can prepare quotations.');const n=db.notifications.find(x=>x.id===request&&x.supplier===user.supplier&&x.items.includes(itemId)),item=db.items.find(i=>i.id===itemId&&i.supplier===user.supplier);if(!n||!item||deskLatestNotice(itemId)?.id!==n.id||requestItemState(n,itemId).state!=='open')return toast('Quotations start from an open price update request from ROKI.');editing=null;editorItem=itemId;editorRequest=request;editorAttachments=[];window.formCosts=n.forms?.[itemId]?structuredClone(n.forms[itemId].costs):startingCosts(editorItem);costTab=sectionsOf(window.formCosts)[0].key;go('new');}
function editQuote(id){const q=visibleQuotes().find(q=>q.id===id);if(!q||!canEdit(q))return toast('This quotation is not editable by this account.');editing=q.id;editorItem=q.item;editorRequest=q.requestedBy;editorAttachments=structuredClone(q.attachments);window.formCosts=costsForEdit(q);costTab=sectionsOf(window.formCosts)[0].key;go('edit/'+id)}
function editor(){if(portal!=='supplier'||user.role!=='Issue')return '<div class="empty">Only supplier issuers may edit quotations.</div>';if(!window.formCosts){const id=location.hash.split('/')[1],q=db.quotes.find(q=>q.id===id&&q.supplier===user.supplier);if(q&&canEdit(q)){editing=q.id;editorItem=q.item;editorRequest=q.requestedBy;editorAttachments=structuredClone(q.attachments);window.formCosts=costsForEdit(q)}else return '<div class="empty">Quotations start from a price update request from ROKI. <a href="#requests" class="link-button">View update requests</a></div>'}if(!sectionsOf(window.formCosts).some(s=>s.key===costTab))costTab=sectionsOf(window.formCosts)[0].key;const q=db.quotes.find(q=>q.id===editing),i=db.items.find(i=>i.id===editorItem),requestSpec=db.notifications.find(n=>n.id===editorRequest)?.forms?.[editorItem],base=q?.baseline||snapshotOf(latestApproved(i.id));
return heading(i.format+' quotation',q?'Revise your quotation':'Prepare a price quotation','Enter costs in the blank form supplied by WEBPARK. Its selected formula calculates the purchase price; submit to your supplier approver when complete.',`<a href="#quotes" class="button">Cancel</a>`)+`<form id="quote-form"><div class="page-grid"><div class="stack"><section class="panel"><div class="panel-title"><div><h2>Quotation details</h2><small>${esc(supplierName(user.supplier))} · Supplier code ${esc(suppliers.find(s=>s.id===user.supplier).code)}</small></div>${statusPill('Draft','gray')}</div><div class="body-pad form-grid"><div class="field"><label for="item">Part / item <span class="req">*</span></label><select id="item" disabled>${[i].map(item=>`<option value="${item.id}" ${i.id===item.id?'selected':''}>${esc(item.code+' · '+item.name)}</option>`).join('')}</select></div><div class="field"><label>Quotation format</label><input readonly value="${esc(i.format)}"></div><div class="field"><label>RTP code</label><input readonly value="${esc(i.rtp||'—')}"></div><div class="field"><label for="effective">Beginning / effective date <span class="req">*</span></label><input id="effective" type="date" value="${q?.effective||requestSpec?.effective||addMonths(TODAY,1)}" required ${requestSpec?'readonly title="Set by ROKI in the request"':''}></div>${requestSpec?.ending?`<div class="field"><label>Ending date</label><input type="date" readonly value="${requestSpec.ending}"></div>`:''}<div class="field"><label for="quantity">${qtyLabelOf(requestSpec?.qtyPeriod||q?.qtyPeriod,i.format)} · pcs <span class="req">*</span></label><input id="quantity" type="number" min="1" step="1" required value="${q?.quantity||requestSpec?.quantity||i.qty||12000}" ${requestSpec?'readonly title="Set by ROKI in the request"':''}></div><div class="field"><label for="drawing">Rev. no. / drawing <span class="req">*</span></label><input id="drawing" value="${esc(q?.drawing||requestSpec?.drawing||i.drawing||'')}" required maxlength="80" ${requestSpec?'readonly title="Set by ROKI in the request"':''}></div>${templateOf(cfgOf(window.formCosts),window.formCosts.format).header.some(h=>h.key==='supplierRef'&&h.show)?`<div class="field"><label for="supplierRef">${esc(templateOf(cfgOf(window.formCosts),window.formCosts.format).header.find(h=>h.key==='supplierRef').label)} (Supplier quotation no.)</label><input id="supplierRef" maxlength="60" value="${esc(q?.supplierRef||'')}"></div>`:''}<div class="field"><label>Previous approved price · THB</label><input readonly value="${base?cash(base.total)+' · Rev. '+base.revision:priceText(i)}"></div></div>${requestInfoNote(requestSpec,db.notifications.find(n=>n.id===editorRequest))}</section><section class="panel"><div class="panel-title"><div><h2>Detailed cost breakdown</h2><small>Same sections as the ROKI ${esc(i.format)} quotation sheet · calculated per piece</small></div></div><div class="cost-tabs">${sectionsOf(window.formCosts).map(s=>`<button type="button" class="${costTab===s.key?'active':''}" data-tab="${s.key}">${s.letter} · ${s.label}</button>`).join('')}</div><div id="cost-rows">${costRowsUI()}</div></section><section class="panel"><div class="panel-title"><h2>Revision reason & attachments</h2></div><div class="body-pad"><div class="field"><label for="remark">Reason for price change <span class="req">*</span></label><textarea id="remark" required maxlength="2000" placeholder="Explain the costs or assumptions that changed…">${esc(q?.remark||'')}</textarea></div><div class="form-grid" style="grid-template-columns:1fr 1fr;margin-top:18px"><div class="field"><label for="images">Part images · up to 10</label><input id="images" type="file" accept="image/png,image/jpeg,image/webp" multiple><small>PNG, JPG or WebP · Up to 2 MB per file in this local demo.</small></div><div class="field"><label for="drawings">Drawing documents</label><input id="drawings" type="file" accept="application/pdf" multiple><small>PDF files only · Up to 2 MB per file.</small></div></div><div id="attachment-list" class="attachment-list">${attachmentUI()}</div></div><div class="form-actions"><small>Supplier Issue → Supplier Approve → WEBPARK Issue → WEBPARK Check → WEBPARK Approve</small><div class="actions"><button type="button" class="button" data-action="save-draft">Save draft</button><button type="submit" class="button primary">Issue for supplier approval ${icon('arrow')}</button></div></div></section></div><aside class="stack"><section class="panel"><div class="panel-title"><h2>Calculated unit price</h2><span class="badge gray">THB / pc</span></div><div class="body-pad"><small>${wfText("Calculated from your inputs; incomplete costs are not a submitted purchase price.","คำนวณจากข้อมูลที่กรอก ต้นทุนที่ยังไม่ครบยังไม่ถือเป็นราคาที่เสนอ")}</small></div><div id="cost-summary">${costSummary(base)}</div></section><div class="highlight-note blue">Calculated with ROKI formula version ${window.formCosts.fv}, effective ${date(formulaVersion(window.formCosts.fv).effective)}. The rounding rules are part of that version.</div></aside></div></form>`}
function formCostRowCount(key){const f=db.notifications.find(n=>n.id===editorRequest)?.forms?.[editorItem]?.costs;return Array.isArray(f?.[key])?f[key].length:0}
function costRowsUI(){const c=window.formCosts,s=sectionsOf(c).find(s=>s.key===costTab),rows=c[s.key];return `<div class="table-wrap"><table class="cost-table"><thead><tr>${s.fields.map(f=>`<th>${f[1]}${isFixedField(s,f)?`<small class="fixed-note">${wfText('Set by WEBPARK','WEBPARK กำหนด')}</small>`:''}</th>`).join('')}<th class="num">Amount</th><th></th></tr></thead><tbody>${rows.map((r,index)=>`<tr>${s.fields.map(([field,label,type,options,flags])=>`<td class="${isFixedField(s,[field,label,type,options,flags])?'fixed-cell':''}">${type==='origin'||type==='choice'?`<select class="cost-input wide" data-cost="${index}" data-field="${field}" ${isFixedField(s,[field,label,type,options,flags])?'disabled title="Set by WEBPARK"':''} aria-label="${label} row ${index+1}">${options.map(o=>`<option value="${o}" ${r[field]===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input class="cost-input ${type==='text'?'wide':''}" type="${type}" data-cost="${index}" data-field="${field}" aria-label="${label} row ${index+1}" value="${esc(r[field])}" ${type==='number'?`min="${flags&&flags.positive?'0.000001':'0'}" step="any" required`:`maxlength="100" ${flags&&flags.req?'required':''}`} ${isFixedField(s,[field,label,type,options,flags])?'readonly tabindex="-1" title="Set by WEBPARK"':''} ${r.link&&field==='rate'?'readonly title="Linked to a sub-part quotation"':''} ${r.supplied&&(field==='rate'||field==='origin')?'readonly':''}>${r.link&&field==='rate'?linkNote(r,index):''}${r.supplied&&field==='rate'?'<small class="link-note">Supplied by ROKI</small>':''}`}</td>`).join('')}<td class="num price" data-expense="${index}">${cash(amountOf(c,s,r))}</td><td>${s.key==='components'&&index<(formCostRowCount(s.key)||0)?'':`<button type="button" class="remove-row" data-remove="${index}" aria-label="Remove row ${index+1}">×</button>`}</td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">No lines in this cost category. Add a row if applicable.</div>':''}</div><div class="cost-row-tools"><button type="button" class="button" data-action="add-cost">${icon('plus')}Add ${s.label.toLowerCase()} line</button>${s.key==='components'&&rows.some(r=>r.link)?'<button type="button" class="button" data-action="refresh-links">Update linked part prices</button>':''}${(s.adj||[]).map(a=>`<label>${esc(a.label)} % <input class="cost-input" data-adj="${a.key}" type="number" min="0" max="100" step="any" value="${c[a.key]}" ${a.lock?'readonly title="Fixed by ROKI"':''}></label>${a.choices?`<label>of <select data-adj-basis="${a.ofKey}" ${a.lock?'disabled':''}>${a.choices.map(x=>`<option value="${x.value}" ${adjChoice(c,a).value===x.value?'selected':''}>${x.label}</option>`).join('')}</select></label>`:''}`).join('')}</div><p class="cost-formula">Formula: ${esc(s.expr)}</p>`}
function costSummary(base){window.formBaseTotal=base?.total;const c=window.formCosts,t=totals(c);return `<div class="cost-totals">${sectionsOf(c).map(s=>`<div><span>${s.letter} · ${s.label}</span><strong data-sum="${s.letter}">${cash(t[s.letter])}</strong></div>`).join('')}<div><span>Subtotal</span><strong data-sum="subtotal">${cash(t.subtotal)}</strong></div><div><span>Profit & admin <input id="profit" aria-label="Profit and admin percentage" type="number" min="0" max="100" step="any" class="cost-input narrow" value="${c.profit}" ${cfgOf(c).profit.lock?'readonly title="Fixed by ROKI"':''}> % of</span><select id="basis" ${cfgOf(c).profit.lock?'disabled':''}>${priceBaseOptions(c).map(o=>`<option value="${o.value}" ${profitBase(c).key===o.value?'selected':''}>${o.label}</option>`).join('')}</select></div><div><span>F · Profit & admin</span><strong data-sum="profit">${cash(t.profit)}</strong></div><div><span>Spare part cost <input id="spare" aria-label="Spare part cost percentage" type="number" min="0" max="100" step="any" class="cost-input narrow" value="${c.spare}" ${cfgOf(c).spare.lock?'readonly title="Fixed by ROKI"':''}> % of ${spareBase(c).short}</span><strong data-sum="spare">${cash(t.spare)}</strong></div><div class="grand"><span>Total unit price</span><strong data-sum="total" data-total>${cash(t.total)}</strong></div>${base?`<div class="calc-note">Last approved: ฿${cash(base.total)} (Rev. ${base.revision}) · change <strong data-sum="change">${signedPct(t.total,base.total)}</strong></div>`:''}</div>`}
function attachmentUI(){return editorAttachments.map((f,i)=>`<span class="attachment-pill">${f.kind==='drawing'?'PDF':'Image'} · ${esc(f.name)} <button type="button" data-remove-file="${i}" aria-label="Remove ${esc(f.name)}">×</button></span>`).join('')}
async function addFiles(input){const files=[...input.files],kind=input.id==='images'?'image':'drawing';if(editorAttachments.length+files.length>14){toast('Maximum 14 files in this local demo.');input.value='';return}if(kind==='image'&&editorAttachments.filter(f=>f.kind==='image').length+files.length>10){toast('Up to 10 part images are allowed.');input.value='';return}for(const file of files){if(file.size>2*1024*1024||!(kind==='image'?['image/png','image/jpeg','image/webp'].includes(file.type):file.type==='application/pdf')){toast('Use a supported file type, maximum 2 MB per file.');continue}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});editorAttachments.push({name:file.name,type:file.type,kind,data})}document.getElementById('attachment-list').innerHTML=attachmentUI();input.value=''}
const usersOf=(portalName,role,supplier)=>users.filter(u=>u.portal===portalName&&(!role||u.role===role)&&(!supplier||u.supplier===supplier));
function email(to,subject,body,quote){if(!to.length)return;subject=CompanyBrand.text(subject);body=CompanyBrand.text(body);db.emails.unshift({id:uid('M'),to:to.map(u=>u.id),subject,body,quote:quote||null,at:timestamp(),by:user?.name||'System'})}
function nextQuoteId(){const y=TODAY.slice(0,4),n=Math.max(100,...db.quotes.map(q=>/^Q-(\d{4})-(\d+)$/.exec(q.id)).filter(m=>m&&m[1]===y).map(m=>+m[2]))+1;return `Q-${y}-${String(n).padStart(4,'0')}`}
function saveQuote(issue){if(portal!=='supplier'||user.role!=='Issue')return;const form=document.getElementById('quote-form');if(issue&&!form.reportValidity())return;const error=issue?validateCosts(window.formCosts):validateDraftCosts(window.formCosts);if(error)return toast(error);if(issue){const lm=missingLinks(window.formCosts);if(lm)return toast(lm)}const notice=db.notifications.find(n=>n.id===editorRequest&&n.supplier===user.supplier&&n.items.includes(editorItem));if(!notice)return toast('The item must belong to this Supplier request.');if(notice.forms?.[editorItem]&&window.formCosts.fv!==notice.forms[editorItem].formulaVersion)return toast('Use the formula version assigned in this request.');const item=db.items.find(i=>i.id===editorItem&&i.supplier===user.supplier);if(!item)return toast('Select an item assigned to your company.');if(!db.quotes.some(x=>x.id===editing)&&!editorRequest)return toast('Quotations start from an open price update request from ROKI.');const old=db.quotes.find(q=>q.id===editing);if(old&&!canEdit(old))return toast('This quotation can no longer be edited.');const remark=document.getElementById('remark').value.trim();if(issue&&!remark)return toast('Add a reason for the revision.');const versions=old?structuredClone(old.versions):[];if(old&&old.status==='Reverted')versions.push({revision:old.revision,status:old.status,total:old.total,remark:old.remark,costs:structuredClone(old.costs),attachments:structuredClone(old.attachments),effective:old.effective,quantity:old.quantity,drawing:old.drawing,previous:old.previous,quoteDate:old.quoteDate,itemSnapshot:old.itemSnapshot?structuredClone(old.itemSnapshot):null,at:timestamp()});const baseline=old?old.baseline:snapshotOf(db.quotes.find(q=>q.id===notice.referencePrices?.[item.id]?.referenceQuote)||latestApproved(item.id));const formSpec=notice.forms?.[item.id];enforceLocks(window.formCosts);if(formSpec){enforceFixedFields(window.formCosts,formSpec.costs);applySupplied(window.formCosts,formSpec)}const costs=structuredClone(window.formCosts),tt=totals(costs),total=tt.total;const q={id:old?.id||nextQuoteId(),item:item.id,supplier:user.supplier,itemSnapshot:notice.forms?.[item.id]?.itemSnapshot||partIdentity(item),format:costs.format,revision:old?old.revision+(old.status==='Reverted'?1:0):Math.max(-1,...db.quotes.filter(q=>q.item===item.id).map(q=>q.revision))+1,status:issue?'Supplier approval':'Draft',previous:baseline?.total??item.price??null,costs,total,totalRaw:tt.totalRaw,quantity:formSpec?formSpec.quantity:Number(document.getElementById('quantity').value),drawing:formSpec?formSpec.drawing:document.getElementById('drawing').value.trim(),effective:formSpec?formSpec.effective:document.getElementById('effective').value,ending:formSpec?.ending||old?.ending||null,qtyPeriod:formSpec?.qtyPeriod||old?.qtyPeriod||null,material:formSpec?.material||'',terms:notice.terms||old?.terms||null,supplierRef:document.getElementById('supplierRef')?document.getElementById('supplierRef').value.trim():(old?.supplierRef||null),quoteDate:TODAY,remark,attachments:structuredClone(editorAttachments),trail:[...(old?.trail||[]),issue?{stage:'S-Issue',action:'Supplier issued for approval',user:user.name,at:timestamp()}:{action:'Supplier saved draft',user:user.name,at:timestamp()}],versions,requestedBy:editorRequest,flowVersion:old?.flowVersion||notice.flowVersion||2,baseline};const prior=db.quotes.slice(),priorEmails=db.emails.slice();if(old)db.quotes=db.quotes.map(x=>x.id===old.id?q:x);else db.quotes.push(q);if(issue)email(usersOf('supplier','Approve',user.supplier),`[ROKI Supplier Price] ${q.id} · ${item.code} waiting for your approval`,`${user.name} issued quotation ${q.id} for ${item.code} ${item.name}: ฿${cash(total)} per piece (${q.previous==null?'first quotation':'previously ฿'+cash(q.previous)}). Reason: ${remark}`,q.id);try{persist()}catch{db.quotes=prior;db.emails=priorEmails;return toast('Browser storage is full. Remove some attachments and try again.')}editing=null;window.formCosts=null;go('quote/'+q.id);toast(issue?'Issued for your supplier approver to review.':'Draft saved.');}
function dialog(title,body,footer,cls=''){document.getElementById('modal-root').innerHTML=`<div class="modal-shade"><section class="dialog ${cls}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></header><div class="dialog-body">${body}</div><footer class="dialog-footer">${actionButton('Cancel','close')}${footer}</footer></section></div>`;document.querySelector('.dialog button')?.focus();}
function closeDialog(){document.getElementById('modal-root').innerHTML=''}
let transitionPending=null;
const quotationNextStage={'Supplier approval':['ROKI Issue','S-Approve'],'ROKI Issue':['ROKI Check','R-Issue'],'ROKI Check':['ROKI Approve','R-Check'],'ROKI Approve':['Approved','R-Approve']};
function transitionAllowed(q,kind){return !!q&&pendingForRole(q)&&(['advance','revert'].includes(kind)||kind==='reject'&&portal==='roki')}
function transitionError(text,field){const error=document.getElementById('transition-error');if(error){error.hidden=false;error.textContent=text}field?.focus()}
function transitionDialog(id,kind){
 const q=visibleQuotes().find(q=>q.id===id);if(!transitionAllowed(q,kind))return toast(wfText('This action is not assigned to your account.','รายการนี้ไม่ได้อยู่ในคิวของบัญชีคุณ'));
 const advance=kind==='advance',supplier=portal==='supplier',check=user.role==='Check',issue=portal==='roki'&&user.role==='Issue';
 transitionPending={id,kind,account:user.id,status:q.status,revision:q.revision,trailLength:q.trail.length};
 const title=advance?(supplier?wfText('Approve and send to WEBPARK','อนุมัติและส่งให้ WEBPARK'):issue?wfText('Issue and send to Check','Issue และส่งให้ Check'):check?wfText('Confirm cost review','ยืนยันตรวจต้นทุน'):wfText('Approve purchase price','อนุมัติราคาซื้อ')):kind==='revert'?wfText('Return for correction','ส่งกลับแก้ไข'):wfText('Reject quotation','ปฏิเสธใบเสนอราคา');
 const outcome=advance?(supplier?wfText('This sends the quotation to WEBPARK Issue.','ใบเสนอราคาจะไปเข้าคิว WEBPARK Issue'):issue?wfText('This sends the quotation to WEBPARK Check.','ใบเสนอราคาจะไปเข้าคิว WEBPARK Check'):check?wfText('This sends the quotation to WEBPARK Approve.','ใบเสนอราคาจะไปเข้าคิว WEBPARK Approve'):wfText('This completes price approval. The price applies from its effective date.','การอนุมัติจะเสร็จสิ้น และราคาจะใช้ตามวันที่มีผล')):kind==='revert'?wfText('Supplier Issue can correct and resubmit the same quotation.','Supplier Issue จะแก้ไขและส่งใบเดิมอีกครั้งได้'):wfText('Supplier Issue will need to submit a replacement quotation.','Supplier Issue จะต้องส่งใบเสนอราคาฉบับใหม่');
 dialog(title,`<p><strong>${esc(q.id)}</strong> · ${esc(itemOf(q)?.name||q.item)} · Rev. ${q.revision}<br><strong>${cash(q.total)} THB</strong></p><p>${outcome}</p><div class="field"><label for="action-reason">${advance?wfText('Review note (optional)','หมายเหตุ (ไม่บังคับ)'):wfText('Reason *','เหตุผล *')}</label><textarea id="action-reason" maxlength="1000"></textarea></div>${advance?`<label class="check transition-confirm"><input id="confirm-action" type="checkbox">${wfText('I confirm as','ยืนยันในนาม')} ${esc(user.name)} · ${esc(user.role)}</label>`:''}<p id="transition-error" class="transition-error" role="alert" hidden></p>`,actionButton(advance?title:wfText('Confirm','ยืนยัน'),'confirm-transition',true));
}
function confirmTransition(){
 const pending=transitionPending,field=document.getElementById('action-reason');if(!pending||!field)return;
 const {id,kind,account,status,revision,trailLength}=pending;
 // Compare against saved data too: another tab may have acted before its storage event reaches this tab.
 let raw,saved;try{raw=localStorage.getItem(STORE);saved=JSON.parse(raw)}catch{return transitionError(wfText('Unable to read saved data. Please try again.','อ่านข้อมูลที่บันทึกไม่ได้ กรุณาลองอีกครั้ง'))}
 const q=db.quotes.find(q=>q.id===id),latest=saved?.quotes.find(q=>q.id===id);
 const sameReview=x=>x&&x.status===status&&x.revision===revision&&x.trail.length===trailLength;
 if(user?.id!==account||!sameReview(q)||!sameReview(latest)||!transitionAllowed(latest,kind)){
  transitionPending=null;closeDialog();if(saved){db=saved;setFormulaStore(db.formulas)}render();return toast(wfText('This quotation changed. Review its latest status before acting.','ใบเสนอราคามีการเปลี่ยนแปลง กรุณาตรวจสถานะล่าสุดก่อนดำเนินการ'));
 }
 const reason=field.value.trim(),check=document.getElementById('confirm-action');
 if(kind!=='advance'&&!reason)return transitionError(wfText('Enter a reason before confirming.','กรอกเหตุผลก่อนกดยืนยัน'),field);
 if(kind==='advance'&&!check?.checked)return transitionError(wfText('Tick the confirmation box before continuing.','ติ๊กช่องยืนยันก่อนดำเนินการ'),check);
 // Apply to the latest saved snapshot so unrelated changes from another tab are retained.
 db=saved;setFormulaStore(db.formulas);
 const item=db.items.find(i=>i.id===latest.item);if(!item)return transitionError(wfText('The part linked to this quotation is missing.','ไม่พบชิ้นส่วนที่เชื่อมกับใบเสนอราคานี้'));
 const tag=`[WEBPARK] ${id} · ${item.code}`,supplierTeam=usersOf('supplier',null,latest.supplier);
 try{
  let action,stage;
  if(kind==='revert'){latest.status='Reverted';action='Returned to supplier issuer for correction';email(portal==='roki'?supplierTeam:usersOf('supplier','Issue',latest.supplier),`${tag} returned for correction`,`${user.name}: ${reason}`,id)}
  else if(kind==='reject'){latest.status='Rejected';action='ROKI rejected quotation';email(supplierTeam,`${tag} rejected`,`${user.name}: ${reason}`,id)}
  else{
   [latest.status,stage]=quotationNextStage[status];action=STAGES.find(s=>s[0]===stage)[1];
   if(latest.status==='Approved'){
    latest.approvedAtISO=new Date().toISOString();syncActivePrices();const hadPrice=item.last!=null;item.last=TODAY;if(item.next||!hadPrice)item.next=addMonths(latest.effective>TODAY?latest.effective:TODAY,item.cadence||3);
    db.history.push({item:item.id,effective:latest.effective,price:latest.total,quote:id,reason:latest.remark});
    email(supplierTeam,`${tag} approved by WEBPARK`,`Approved at ${cash(latest.total)} THB per piece, effective ${date(latest.effective)}.`,id);
   }else{const role=latest.status.replace('ROKI ','');email(usersOf('roki',role),`${tag} waiting for WEBPARK ${role}`,`${user.name} completed ${stage}. Proposed price: ${cash(latest.total)} THB per piece.`,id)}
  }
  latest.trail.push({stage,action,user:user.name,at:timestamp(),reason});db.audit.unshift({action:action+' · '+id,user:user.name,at:timestamp(),reason});persist();
 }catch{
  // A failed write must not advance the visible workflow or leave a partial audit record.
  db=JSON.parse(raw);setFormulaStore(db.formulas);
  return transitionError(wfText('Could not save this action. The quotation remains in its previous stage. Check browser storage and try again.','บันทึกไม่ได้ ใบเสนอราคายังอยู่ขั้นตอนเดิม กรุณาตรวจพื้นที่จัดเก็บของเบราว์เซอร์แล้วลองอีกครั้ง'));
 }
 transitionPending=null;closeDialog();render();toast(wfText('Saved: ','บันทึกแล้ว: ')+wfQuoteLabel(latest.status,stageLabels[latest.status][0]));
}
